userContent.text:
Here is the generated code to evaluate:

<!-- @FIGURE_UI_BEGIN -->
<div style="margin-bottom: 10px;">
  <p id="demoNarration" style="margin:0 0 10px 0; font-size:12px; line-height:1.45;"></p>
  <div style="display:flex; align-items:center; justify-content:space-between; background:#f0f2f5; padding:6px 8px; border-radius:6px; border:1px solid #dcdfe3;">
    <button id="btnPrev" onclick="prevStep()" style="padding:4px 12px; font-size:12px;">◀</button>
    <span id="stepLabel" style="font-weight:600; font-size:11px; color:#444;"></span>
    <button id="btnNext" onclick="nextStep()" style="padding:4px 12px; font-size:12px;">▶</button>
  </div>
</div>
<!-- @FIGURE_UI_END -->
// @FIGURE_CODE_BEGIN
const W = 900, H = 550;
const draw = SVG().addTo('#container').size('100%', '100%').viewbox(0, 0, W, H);

// Layers to preserve z-ordering
const layerRays = draw.group();
const layerLines = draw.group();
const layerPoints = draw.group();
const layerLabels = draw.group();

// Application State
let currentStep = 0;
const steps = [
    {
        title: "Defining the Cross-Ratio",
        narration: "Four collinear points P₁–P₄ define a cross-ratio based on their relative distances. Drag the points along the line to change this fundamental value.",
        state: 0
    },
    {
        title: "Central Projection",
        narration: "Projecting these points from center O to a new line Q creates points Q₁–Q₄. Try moving O — the distances change drastically, but the cross-ratio is preserved.",
        state: 1
    },
    {
        title: "Points at Infinity",
        narration: "If a transversal line R is parallel to one of the rays, its intersection R₁ lies at infinity. The cross-ratio still holds, with the infinite terms taking a limit of 1.",
        state: 2
    }
];

// Geometry Definitions
let O = { x: 50, y: 400 };
let t = [0.1, 0.35, 0.6, 0.85]; // Parameters for points on Line P

const PA = { x: 220, y: 500 };
const PB = { x: 280, y: 50 };
const QA = { x: 450, y: 500 };
const QB = { x: 350, y: 50 };
const RA = { x: 250, y: 20 }; // Base point for R

function getP(ti) {
    return {
        x: PA.x + ti * (PB.x - PA.x),
        y: PA.y + ti * (PB.y - PA.y)
    };
}

function getIntersect(A1, D1, A2, D2) {
    let det = D1.x * D2.y - D1.y * D2.x;
    if (Math.abs(det) < 1e-6) return null;
    let u = ((A2.x - A1.x) * D2.y - (A2.y - A1.y) * D2.x) / det;
    return { x: A1.x + u * D1.x, y: A1.y + u * D1.y };
}

// Styling & Helpers
function addHalo(textObj) {
    textObj.attr({ 'paint-order': 'stroke', stroke: '#fff', 'stroke-width': 4, 'stroke-linejoin': 'round' });
}

function makeLabelObj(str, sub) {
    let t = layerLabels.text('');
    t.tspan(str).font({ size: 18, style: 'italic', family: 'serif' });
    if (sub) t.tspan(sub).font({ size: 12, family: 'serif' }).dy(5);
    addHalo(t);
    return t;
}

// Visual Elements
const raysLines = [];
for (let i = 0; i < 4; i++) raysLines.push(layerRays.line().stroke({ width: 1.5, color: '#222' }));

const linePShape = layerLines.line().stroke({ width: 2.5, color: '#d81b60' });
const lineQShape = layerLines.line().stroke({ width: 2.5, color: '#d81b60' });
const lineRShape = layerLines.line().stroke({ width: 2.5, color: '#d81b60' });

const ptO = layerPoints.circle(12).fill('#000').stroke({ color: '#fff', width: 2 }).css('cursor', 'pointer');
const ptsP = [], ptsQ = [], ptsR = [];
for (let i = 0; i < 4; i++) ptsP.push(layerPoints.circle(12).fill('#000').stroke({ color: '#fff', width: 2 }).css('cursor', 'pointer'));
for (let i = 0; i < 4; i++) ptsQ.push(layerPoints.circle(9).fill('#000'));
for (let i = 0; i < 3; i++) ptsR.push(layerPoints.circle(9).fill('#000'));

const labelO = makeLabelObj('O');
const labelsP = ['1', '2', '3', '4'].map(n => makeLabelObj('P', n));
const labelsQ = ['1', '2', '3', '4'].map(n => makeLabelObj('Q', n));
const labelsR = ['2', '3', '4'].map(n => makeLabelObj('R', n));

const labelR1 = layerLabels.text('');
labelR1.tspan('R').font({ size: 18, style: 'italic', family: 'serif' });
labelR1.tspan('1').font({ size: 12, family: 'serif' }).dy(5);
labelR1.tspan(' → ∞').font({ size: 18, family: 'sans-serif' }).dy(-5);
addHalo(labelR1);

const mathBox = layerLabels.rect().fill('#fff').radius(4).stroke({ color: '#d81b60', width: 1.5 }).opacity(0.95);
const textMath = layerLabels.text('').font({ family: 'monospace', size: 15, weight: 'bold' }).fill('#d81b60');

// Hover effects
[ptO, ...ptsP].forEach(pt => {
    pt.on('mouseover', () => pt.stroke({ color: '#2196F3', width: 3 }));
    pt.on('mouseout', () => pt.stroke({ color: '#fff', width: 2 }));
    pt.on('mousemove', e => showTooltip('Drag to move', e));
    pt.on('mouseleave', () => hideTooltip());
});

// Update Function
function update() {
    let RAYS = [];
    for (let i = 0; i < 4; i++) {
        let p = getP(t[i]);
        let dir = { x: p.x - O.x, y: p.y - O.y };
        RAYS.push({ A: O, D: dir });
        raysLines[i].plot(O.x, O.y, O.x + dir.x * 20, O.y + dir.y * 20);
        ptsP[i].center(p.x, p.y);
        labelsP[i].move(p.x - 28, p.y - 25);
    }

    let DP = { x: PB.x - PA.x, y: PB.y - PA.y };
    linePShape.plot(PA.x - 0.3 * DP.x, PA.y - 0.3 * DP.y, PB.x + 0.3 * DP.x, PB.y + 0.3 * DP.y);

    let DQ = { x: QB.x - QA.x, y: QB.y - QA.y };
    let Q_line = { A: QA, D: DQ };
    lineQShape.plot(QA.x - 0.5 * DQ.x, QA.y - 0.5 * DQ.y, QB.x + 1.2 * DQ.x, QB.y + 1.2 * DQ.y);

    for (let i = 0; i < 4; i++) {
        let qInt = getIntersect(RAYS[i].A, RAYS[i].D, Q_line.A, Q_line.D);
        if (qInt) {
            ptsQ[i].center(qInt.x, qInt.y);
            labelsQ[i].move(qInt.x + 12, qInt.y - 12);
        }
    }

    let R_line = { A: RA, D: RAYS[0].D };
    lineRShape.plot(RA.x - 0.5 * R_line.D.x, RA.y - 0.5 * R_line.D.y, RA.x + 6 * R_line.D.x, RA.y + 6 * R_line.D.y);

    for (let i = 1; i < 4; i++) {
        let rInt = getIntersect(RAYS[i].A, RAYS[i].D, R_line.A, R_line.D);
        if (rInt) {
            ptsR[i - 1].center(rInt.x, rInt.y);
            labelsR[i - 1].move(rInt.x + 12, rInt.y - 12);
        }
    }

    let sx = (840 - R_line.A.x) / R_line.D.x;
    labelR1.move(840, R_line.A.y + sx * R_line.D.y - 28);

    ptO.center(O.x, O.y);
    labelO.move(O.x - 25, O.y - 15);

    // Cross-Ratio math
    let cr = ((t[2] - t[0]) * (t[3] - t[1])) / ((t[2] - t[1]) * (t[3] - t[0]));
    let crStr = cr.toFixed(3);

    let mathStr = "CR(P) = " + crStr;
    if (currentStep >= 1) mathStr = "CR(P) = CR(Q) = " + crStr;
    if (currentStep >= 2) mathStr = "CR(P) = CR(Q) = CR(R) = " + crStr;

    textMath.text(mathStr).move(25, 25);
    let bbox = textMath.bbox();
    mathBox.size(bbox.w + 20, bbox.h + 10).move(15, 20);

    // Visibility
    let showQ = currentStep >= 1;
    let showR = currentStep >= 2;

    lineQShape.opacity(showQ ? 1 : 0);
    ptsQ.forEach(pt => pt.opacity(showQ ? 1 : 0));
    labelsQ.forEach(l => l.opacity(showQ ? 1 : 0));

    lineRShape.opacity(showR ? 1 : 0);
    ptsR.forEach(pt => pt.opacity(showR ? 1 : 0));
    labelsR.forEach(l => l.opacity(showR ? 1 : 0));
    labelR1.opacity(showR ? 1 : 0);
}

// Input Handling
function getMouseCoords(e) {
    let pt = draw.node.createSVGPoint();
    pt.x = e.clientX;
    pt.y = e.clientY;
    let ctm = draw.node.getScreenCTM();
    return ctm ? pt.matrixTransform(ctm.inverse()) : { x: pt.x, y: pt.y };
}

let draggingO = false;
let draggingP = -1;

ptO.on('mousedown', () => { draggingO = true; hideTooltip(); });
ptsP.forEach((pt, i) => {
    pt.on('mousedown', () => { draggingP = i; hideTooltip(); });
});

window.addEventListener('mousemove', e => {
    if (draggingO) {
        let pt = getMouseCoords(e);
        O.x = Math.max(10, Math.min(180, pt.x));
        O.y = Math.max(80, Math.min(500, pt.y));
        update();
    } else if (draggingP !== -1) {
        let pt = getMouseCoords(e);
        let DP = { x: PB.x - PA.x, y: PB.y - PA.y };
        let len2 = DP.x * DP.x + DP.y * DP.y;
        let newT = ((pt.x - PA.x) * DP.x + (pt.y - PA.y) * DP.y) / len2;

        let minT = (draggingP > 0) ? t[draggingP - 1] + 0.05 : -0.1;
        let maxT = (draggingP < 3) ? t[draggingP + 1] - 0.05 : 1.1;

        t[draggingP] = Math.max(minT, Math.min(maxT, newT));
        update();
    }
});

window.addEventListener('mouseup', () => { draggingO = false; draggingP = -1; });

// Step Player
function setStep(idx) {
    currentStep = Math.max(0, Math.min(2, idx));
    let step = steps[currentStep];
    document.getElementById('demoNarration').innerHTML = `<strong>${step.title}</strong><br/>${step.narration}`;
    document.getElementById('stepLabel').textContent = `Step ${currentStep + 1} of 3`;
    document.getElementById('btnPrev').disabled = (currentStep === 0);
    document.getElementById('btnNext').disabled = (currentStep === steps.length - 1);
    update();
}

window.prevStep = () => setStep(currentStep - 1);
window.nextStep = () => setStep(currentStep + 1);

// Initialize
setStep(0);
window.__markRendered();
// @FIGURE_CODE_END

