function getIntersect(A1, D1, A2, D2) {
    let det = D1.x * D2.y - D1.y * D2.x;
    if (Math.abs(det) < 1e-6) return null;
    let u = ((A2.x - A1.x) * D2.y - (A2.y - A1.y) * D2.x) / det;
    return { x: A1.x + u * D1.x, y: A1.y + u * D1.y };
}

