function getIntersect(A, DA, B, DB) {
    let det = DA.x * DB.y - DA.y * DB.x;
    if (Math.abs(det) < 1e-6) return null;
    let u = ((B.x - A.x) * DB.y - (B.y - A.y) * DB.x) / det;
    return { x: A.x + u * DA.x, y: A.y + u * DA.y };
}

function normalize(v) {
    let len = Math.sqrt(v.x*v.x + v.y*v.y);
    return len === 0 ? {x: 1, y: 0} : {x: v.x/len, y: v.y/len};
}

