const lblO = makeLabel('O');
const lblsP = ['1', '2', '3', '4'].map(n => makeLabel('P', n));
const lblsQ = ['1', '2', '3', '4'].map(n => makeLabel('Q', n));
const lblsR = ['2', '3', '4'].map(n => makeLabel('R', n));

const lblR1 = layerLabels.text(add => {
    add.tspan('R').font({ size: 26, family: 'Times New Roman, serif', weight: 'bold' });
