lblR1.attr({ 'paint-order': 'stroke', stroke: '#fff', 'stroke-width': 5, 'stroke-linejoin': 'round' });

// Hovers
const attachLineHover = (hit, shape, title) => {
    hit.on('mouseover', e => { shape.stroke({ width: 4.5 }); showTooltip(`Drag to translate Line ${title}`, e); });
    hit.on('mouseout', () => { shape.stroke({ width: 2.5 }); hideTooltip(); });
