// @FIGURE_CODE_BEGIN
const W = 950, H = 550;
const draw = SVG().addTo('#container').size('100%', '100%').viewbox(0, 0, W, H);

// Layers to preserve strict rendering order
const layerRays = draw.group();
const layerLines = draw.group();
const layerHit = draw.group(); 
const layerPoints = draw.group();
const layerLabels = draw.group();

// Application State
let O, PA, PB, t, QA, QB, RA;

// Math Helpers
function getIntersect(A, DA, B, DB) {
    let det = DA.x * DB.y - DA.y * DB.x;
    if (Math.abs(det) < 1e-6) return null;
    let u = ((B.x - A.x) * DB.y - (B.y - A.y) * DB.x) / det;
    return { x: A.x + u * DA.x, y: A.y + u * DA.y };
}

function normalize(v) {
    let len = Math.sqrt(v.x*v.x + v.y*v.y);
    return len === 0 ? {x: 1, y: 0} : {x: v.x/len, y: v.y/len};
}

// Styling & Label Helpers
const makeLabel = (str, sub) => {
    return layerLabels.text(add => {
        add.tspan(str).font({ size: 28, family: 'Times New Roman, serif', weight: 'bold' });
        if (sub) {
            add.tspan(sub).font({ size: 16, family: 'Times New Roman, serif', weight: 'bold' }).dy(10);
        }
    });
};

const lblR1 = layerLabels.text(add => {
    add.tspan('R').font({ size: 28, family: 'Times New Roman, serif', weight: 'bold' });
    add.tspan('1').font({ size: 16, family: 'Times New Roman, serif', weight: 'bold' }).dy(10);
    add.tspan(' → ∞').font({ size: 28, family: 'sans-serif', weight: 'normal' }).dy(-10);
});

// Visual Elements
const shapeRays = Array(4).fill(0).map(() => layerRays.line().stroke({ width: 2, color: '#111' }));
const shapeP = layerLines.line().stroke({ width: 2.5, color: '#e91e63' });
const shapeQ = layerLines.line().stroke({ width: 2.5, color: '#e91e63' });
const shapeR = layerLines.line().stroke({ width: 2.5, color: '#e91e63' });

// Invisible thick lines for draggable transversals
const hitStroke = { width: 40, color: 'transparent' };
const hitP = layerHit.line().stroke(hitStroke).css('cursor', 'move');
const hitQ = layerHit.line().stroke(hitStroke).css('cursor', 'move');
const hitR = layerHit.line().stroke(hitStroke).css('cursor', 'move');

const ptO = layerPoints.circle(16).fill('#000').css('cursor', 'pointer');
const ptsP = Array(4).fill(0).map(() => layerPoints.circle(14).fill('#000').css('cursor', 'pointer'));
const ptsQ = Array(4).fill(0).map(() => layerPoints.circle(14).fill('#000'));
const ptsR = Array(3).fill(0).map(() => layerPoints.circle(14).fill('#000'));

const lblO = makeLabel('O');
const lblsP = ['1', '2', '3', '4'].map(n => makeLabel('P', n));
const lblsQ = ['1', '2', '3', '4'].map(n => makeLabel('Q', n));
const lblsR = ['2', '3', '4'].map(n => makeLabel('R', n));

// Hovers
const attachLineHover = (hit, shape, title) => {
    hit.on('mouseover', e => { shape.stroke({ width: 4.5 }); showTooltip(`Drag to translate Line ${title}`, e); });
    hit.on('mouseout', () => { shape.stroke({ width: 2.5 }); hideTooltip(); });
    hit.on('mousemove', e => showTooltip(`Drag to translate Line ${title}`, e));
};
attachLineHover(hitP, shapeP, 'P');
attachLineHover(hitQ, shapeQ, 'Q');
attachLineHover(hitR, shapeR, 'R');

ptO.on('mouseover', e => { ptO.stroke({ color: '#2196F3', width: 3 }); showTooltip('Drag center O', e); });
ptO.on('mouseout', () => { ptO.stroke('none'); hideTooltip(); });

ptsP.forEach((pt, i) => {
    pt.on('mouseover', e => { pt.stroke({ color: '#2196F3', width: 3 }); showTooltip(`Drag P${i+1} along line`, e); });
    pt.on('mouseout', () => { pt.stroke('none'); hideTooltip(); });
});
ptsQ.forEach((pt, i) => {
    pt.on('mouseover', e => showTooltip(`Intersection Q${i+1}`, e));
    pt.on('mouseout', () => hideTooltip());
});
ptsR.forEach((pt, i) => {
    pt.on('mouseover', e => showTooltip(`Intersection R${i+2}`, e));
    pt.on('mouseout', () => hideTooltip());
});

// Core Geometry Update
function update() {
    let DP = { x: PB.x - PA.x, y: PB.y - PA.y };
    let P_pts = t.map(val => ({ x: PA.x + val * DP.x, y: PA.y + val * DP.y }));
    let rays = P_pts.map(p => ({ A: O, D: normalize({ x: p.x - O.x, y: p.y - O.y }) }));

    let DQ = { x: QB.x - QA.x, y: QB.y - QA.y };
    let Q_pts = rays.map(r => getIntersect(r.A, r.D, QA, DQ));

    let DR = rays[0].D; // R remains strictly parallel to Ray 1
    let R_pts = [1, 2, 3].map(i => getIntersect(rays[i].A, rays[i].D, RA, DR));

    // Safely bounded visual segments
    let dP_pts = P_pts.map(pt => (pt.x - PA.x)*DP.x + (pt.y - PA.y)*DP.y);
    let DP_mag2 = DP.x*DP.x + DP.y*DP.y || 1;
    let padP = 40 / Math.sqrt(DP_mag2), hitPadP = 60 / Math.sqrt(DP_mag2);
    let tMinP = Math.min(...dP_pts)/DP_mag2, tMaxP = Math.max(...dP_pts)/DP_mag2;
    shapeP.plot(PA.x + (tMinP - padP)*DP.x, PA.y + (tMinP - padP)*DP.y, PA.x + (tMaxP + padP)*DP.x, PA.y + (tMaxP + padP)*DP.y);
    hitP.plot(PA.x + (tMinP - hitPadP)*DP.x, PA.y + (tMinP - hitPadP)*DP.y, PA.x + (tMaxP + hitPadP)*DP.x, PA.y + (tMaxP + hitPadP)*DP.y);

    let validQ = Q_pts.filter(pt => pt);
    if (validQ.length > 1) {
        let dQ_pts = validQ.map(pt => (pt.x - QA.x)*DQ.x + (pt.y - QA.y)*DQ.y);
        let DQ_mag2 = DQ.x*DQ.x + DQ.y*DQ.y || 1;
        let padQ = 40 / Math.sqrt(DQ_mag2), hitPadQ = 60 / Math.sqrt(DQ_mag2);
        let tMinQ = Math.min(...dQ_pts)/DQ_mag2, tMaxQ = Math.max(...dQ_pts)/DQ_mag2;
        shapeQ.plot(QA.x + (tMinQ - padQ)*DQ.x, QA.y + (tMinQ - padQ)*DQ.y, QA.x + (tMaxQ + padQ)*DQ.x, QA.y + (tMaxQ + padQ)*DQ.y);
        hitQ.plot(QA.x + (tMinQ - hitPadQ)*DQ.x, QA.y + (tMinQ - hitPadQ)*DQ.y, QA.x + (tMaxQ + hitPadQ)*DQ.x, QA.y + (tMaxQ + hitPadQ)*DQ.y);
    }

    let validR = R_pts.filter(pt => pt);
    if (validR.length > 1) {
        let dR_pts = validR.map(pt => (pt.x - RA.x)*DR.x + (pt.y - RA.y)*DR.y);
        let DR_mag2 = DR.x*DR.x + DR.y*DR.y || 1;
        let padRMin = 40 / Math.sqrt(DR_mag2), padRMax = 120 / Math.sqrt(DR_mag2), hitPadR = 120 / Math.sqrt(DR_mag2);
        let tMinR = Math.min(...dR_pts)/DR_mag2, tMaxR = Math.max(...dR_pts)/DR_mag2;
        shapeR.plot(RA.x + (tMinR - padRMin)*DR.x, RA.y + (tMinR - padRMin)*DR.y, RA.x + (tMaxR + padRMax)*DR.x, RA.y + (tMaxR + padRMax)*DR.y);
        hitR.plot(RA.x + (tMinR - hitPadR)*DR.x, RA.y + (tMinR - hitPadR)*DR.y, RA.x + (tMaxR + hitPadR)*DR.x, RA.y + (tMaxR + hitPadR)*DR.y);
        lblR1.show().move(RA.x + (tMaxR + padRMax - 80)*DR.x, RA.y + (tMaxR + padRMax - 80)*DR.y - 25);
    } else {
        lblR1.hide();
    }

    rays.forEach((r, i) => {
        let ptsOnRay = [ P_pts[i], Q_pts[i] ];
        if (i > 0) ptsOnRay.push(R_pts[i-1]);

        let maxDist = 0;
        ptsOnRay.forEach(pt => {
            if (!pt) return;
            let dot = (pt.x - O.x) * r.D.x + (pt.y - O.y) * r.D.y;
            if (dot > maxDist) maxDist = dot;
        });
        shapeRays[i].plot(O.x, O.y, O.x + r.D.x * (maxDist + 50), O.y + r.D.y * (maxDist + 50));
    });

    // Positioning Markers and Labels
    ptO.center(O.x, O.y);
    lblO.move(O.x - 32, O.y - 20);

    P_pts.forEach((p, i) => {
        ptsP[i].center(p.x, p.y);
        lblsP[i].move(p.x + 10, p.y + 0);
    });

    Q_pts.forEach((q, i) => {
        if (q) {
            ptsQ[i].show().center(q.x, q.y);
            lblsQ[i].show().move(q.x + 10, q.y + 0);
        } else {
            ptsQ[i].hide(); lblsQ[i].hide();
        }
    });

    R_pts.forEach((r, i) => {
        if (r) {
            ptsR[i].show().center(r.x, r.y);
            lblsR[i].show().move(r.x - 32, r.y - 35);
        } else {
            ptsR[i].hide(); lblsR[i].hide();
        }
    });
}

// Interactivity
let activeDrag = null;

function getMouse(e) {
    let pt = draw.node.createSVGPoint();
    pt.x = e.clientX; pt.y = e.clientY;
    let ctm = draw.node.getScreenCTM();
    return ctm ? pt.matrixTransform(ctm.inverse()) : { x: pt.x, y: pt.y };
}

ptO.on('mousedown', e => { activeDrag = { type: 'O' }; hideTooltip(); e.stopPropagation(); });

ptsP.forEach((pt, i) => {
    pt.on('mousedown', e => { activeDrag = { type: 'P_pt', idx: i }; hideTooltip(); e.stopPropagation(); });
});

[
    { hit: hitP, id: 'P', getA: () => PA, getB: () => PB },
    { hit: hitQ, id: 'Q', getA: () => QA, getB: () => QB },
    { hit: hitR, id: 'R', getA: () => RA, getB: () => ({x:0,y:0}) }
].forEach(target => {
    target.hit.on('mousedown', e => {
        activeDrag = { type: 'Line', id: target.id, startMouse: getMouse(e), startA: { ...target.getA() }, startB: { ...target.getB() } };
        hideTooltip(); e.stopPropagation();
    });
});

window.addEventListener('mousemove', e => {
    if (!activeDrag) return;
    let m = getMouse(e);

    if (activeDrag.type === 'O') {
        O.x = Math.min(200, Math.max(10, m.x));
        O.y = Math.min(520, Math.max(30, m.y));
        update();
    } 
    else if (activeDrag.type === 'P_pt') {
        let idx = activeDrag.idx;
        let DP = { x: PB.x - PA.x, y: PB.y - PA.y };
        let new_t = ((m.x - PA.x) * DP.x + (m.y - PA.y) * DP.y) / (DP.x * DP.x + DP.y * DP.y || 1);
        t[idx] = Math.max((idx > 0) ? t[idx-1] + 0.04 : -0.5, Math.min((idx < 3) ? t[idx+1] - 0.04 : 1.5, new_t));
        update();
    } 
    else if (activeDrag.type === 'Line') {
        let dx = m.x - activeDrag.startMouse.x, dy = m.y - activeDrag.startMouse.y;
        if (activeDrag.id === 'P') {
            PA.x = activeDrag.startA.x + dx; PA.y = activeDrag.startA.y + dy;
            PB.x = activeDrag.startB.x + dx; PB.y = activeDrag.startB.y + dy;
        } else if (activeDrag.id === 'Q') {
            QA.x = activeDrag.startA.x + dx; QA.y = activeDrag.startA.y + dy;
            QB.x = activeDrag.startB.x + dx; QB.y = activeDrag.startB.y + dy;
        } else if (activeDrag.id === 'R') {
            RA.x = activeDrag.startA.x + dx; RA.y = activeDrag.startA.y + dy;
        }
        update();
    }
});
window.addEventListener('mouseup', () => { activeDrag = null; });

window.resetFigure = () => {
    O = { x: 50, y: 350 };
    PA = { x: 230, y: 440 }; PB = { x: 280, y: 190 };
    t = [0, 0.4, 0.65, 1]; 
    QA = { x: 400, y: 500 }; QB = { x: 300, y: 160 };
    RA = { x: 450, y: 110 }; 
    if (typeof update === 'function') update();
};

window.resetFigure();
window.__markRendered();
// @FIGURE_CODE_END

